create extension if not exists pgcrypto;
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,plan text not null default 'core',subscription_status text not null default 'trial',country_code text default 'AR',currency_code text default 'ARS',created_at timestamptz not null default now());
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,organization_id uuid references public.organizations(id) on delete set null,full_name text,role text not null default 'owner',created_at timestamptz not null default now());
create table if not exists public.clients(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,tax_id text,email text,phone text,notes text,created_at timestamptz default now());
create table if not exists public.branches(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,client_id uuid not null references public.clients(id) on delete cascade,name text not null,address text,city text,province text,country text default 'Argentina',created_at timestamptz default now());
create table if not exists public.warehouses(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,type text not null default 'standard',address text,active boolean not null default true,created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,sku text,name text not null,category text,unit text default 'unit',track_lots boolean default false,track_serials boolean default false,requires_compatible_lot boolean default false,flightcase_capacity integer,weight_kg numeric(12,3),volume_m3 numeric(12,4),created_at timestamptz default now());
create table if not exists public.lots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,code text not null,lot_type text default 'purchase',parent_lot_id uuid references public.lots(id) on delete set null,supplier text,received_at date,technical_notes text,active boolean default true,unique(organization_id,product_id,code));
create table if not exists public.inventory_balances(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,lot_id uuid references public.lots(id) on delete cascade,warehouse_id uuid not null references public.warehouses(id) on delete cascade,state text not null default 'available',quantity numeric(14,3) default 0);
create table if not exists public.events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,client_id uuid references public.clients(id) on delete set null,branch_id uuid references public.branches(id) on delete set null,name text not null,location text,setup_at timestamptz,event_at timestamptz,teardown_at timestamptz,status text default 'draft',notes text,created_at timestamptz default now());
create table if not exists public.event_reservations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,event_id uuid not null references public.events(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,lot_id uuid references public.lots(id) on delete set null,quantity numeric(14,3) not null,status text default 'reserved',created_at timestamptz default now());
create table if not exists public.repairs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,lot_id uuid references public.lots(id) on delete set null,serial_code text,quantity numeric(14,3) default 1,failure_type text,damage_zone text,probable_cause text,related_event_id uuid references public.events(id) on delete set null,priority text default 'normal',status text default 'pending',opened_at timestamptz default now(),closed_at timestamptz,notes text);
create table if not exists public.vehicles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,plate text,vehicle_type text,usable_length_m numeric(10,2),usable_width_m numeric(10,2),usable_height_m numeric(10,2),max_weight_kg numeric(12,2),status text default 'available');
create table if not exists public.flight_cases(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,code text not null,compatible_product_id uuid references public.products(id) on delete set null,capacity_units integer,length_m numeric(10,2),width_m numeric(10,2),height_m numeric(10,2),empty_weight_kg numeric(10,2),status text default 'available',unique(organization_id,code));
create table if not exists public.organization_features(organization_id uuid primary key references public.organizations(id) on delete cascade,led_operations boolean default false,lighting_operations boolean default false,audio_operations boolean default false,advanced_logistics boolean default false,analytics_pro boolean default false);
create or replace function public.current_org_id() returns uuid language sql stable security definer set search_path=public as $$ select organization_id from public.profiles where id=auth.uid() $$;
alter table public.organizations enable row level security; alter table public.profiles enable row level security; alter table public.clients enable row level security; alter table public.branches enable row level security; alter table public.warehouses enable row level security; alter table public.products enable row level security; alter table public.lots enable row level security; alter table public.inventory_balances enable row level security; alter table public.events enable row level security; alter table public.event_reservations enable row level security; alter table public.repairs enable row level security; alter table public.vehicles enable row level security; alter table public.flight_cases enable row level security; alter table public.organization_features enable row level security;
create policy "profiles_select_own" on public.profiles for select using(id=auth.uid() or organization_id=public.current_org_id());
create policy "profiles_update_own" on public.profiles for update using(id=auth.uid());
create policy "org_select_member" on public.organizations for select using(id=public.current_org_id());
create policy "clients_org_all" on public.clients for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create policy "branches_org_all" on public.branches for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create policy "warehouses_org_all" on public.warehouses for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create policy "products_org_all" on public.products for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create policy "lots_org_all" on public.lots for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create policy "inventory_org_all" on public.inventory_balances for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create policy "events_org_all" on public.events for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create policy "reservations_org_all" on public.event_reservations for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create policy "repairs_org_all" on public.repairs for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create policy "vehicles_org_all" on public.vehicles for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create policy "flightcases_org_all" on public.flight_cases for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create policy "features_org_all" on public.organization_features for all using(organization_id=public.current_org_id()) with check(organization_id=public.current_org_id());
create or replace function public.bootstrap_my_organization(p_name text,p_slug text) returns uuid language plpgsql security definer set search_path=public as $$ declare v_org uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if exists(select 1 from public.profiles where id=auth.uid() and organization_id is not null) then select organization_id into v_org from public.profiles where id=auth.uid(); return v_org; end if; insert into public.organizations(name,slug) values(p_name,lower(regexp_replace(p_slug,'[^a-zA-Z0-9-]+','-','g'))) returning id into v_org; insert into public.profiles(id,organization_id,role) values(auth.uid(),v_org,'owner') on conflict(id) do update set organization_id=excluded.organization_id,role='owner'; insert into public.organization_features(organization_id) values(v_org) on conflict do nothing; return v_org; end; $$;
grant execute on function public.bootstrap_my_organization(text,text) to authenticated; grant execute on function public.current_org_id() to authenticated;
